args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birth ?death ?ageYears WHERE {
  VALUES ?person { dbr:Aniela_Pawlikowska dbr:Erling_Jensen }
  OPTIONAL { ?person dbo:birthDate ?birth . }
  OPTIONAL { ?person dbo:deathDate ?death . }
  OPTIONAL {
    ?person dbp:birthDate ?birthAlt .
  }
  OPTIONAL {
    ?person dbp:deathDate ?deathAlt .
  }
  BIND(COALESCE(?birth, ?birthAlt) AS ?b)
  BIND(COALESCE(?death, ?deathAlt) AS ?d)
  FILTER(bound(?b) && bound(?d))
  # ensure xsd:date typed values
  BIND(xsd:date(?b) AS ?bdate)
  BIND(xsd:date(?d) AS ?ddate)
  BIND( (year(?ddate) - year(?bdate)) AS ?ydiff)
  BIND( IF( ( (month(?ddate) < month(?bdate)) || ( (month(?ddate) = month(?bdate)) && (day(?ddate) < day(?bdate)) ) ), 1, 0) AS ?sub )
  BIND(?ydiff - ?sub AS ?ageYears)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = "en") }
}
ORDER BY ?personLabel

PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?abs WHERE { dbr:Aniela_Pawlikowska dbo:abstract ?abs . FILTER(lang(?abs) = "en") }

